// ICSE 9 Mathematics ch07 Logarithms — practice bank with independent re-solve checks.
// Answers, keys and option values are typed as literals; each check recomputes them with logs.mjs: exact rational values
// of log_b a from prime-exponent vectors (logExact) and BigInt power checks (powEq); every law-based simplification as an
// exact vector identity plus a numeric check to 1e-12 (law, numExp); every given-decimal problem in exact decimal arithmetic
// (fromGiven, dadd, dsub, dmul); every domain statement by scanning test values.
import { Q, mk, r } from './lib.mjs';
import { logExact, ratTex, powEq, law, vcomb, vecOf, vEq, rat, fromGiven, dadd, dsub, dmul, digitsOf, firstPowerAbove, lg, near } from './logs.mjs';

const O = (a) => a.map((s) => `$${s}$`);
const LT = (b, a) => ratTex(logExact(b, a)); // exact log_b a as TeX
const pick = (C, opts, test) => C.which(opts.map((o) => (test(o) ? 1 : 0)), 1); // exactly one typed option passes the independent test
const PTS = [[2.3, 5.1, 1.7, 3.9], [11, 0.4, 3.2, 2.6], [7.5, 9.1, 0.2, 1.3]];
/** sum c_i log v_i equals log of prod v_i^e_i at three sample points (symbolic expansion check) */
const numExp = (cs, es) => PTS.every((p) => Math.abs(cs.reduce((s, c, i) => s + c * Math.log10(p[i]), 0) - Math.log10(es.reduce((m, e, i) => m * p[i] ** e, 1))) < 1e-12);
const isLog = (b, a, x) => { const e = logExact(b, a); return !!e && e.n * x[1] === x[0] * e.d; };

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: r`Imran's notebook records the fact $4^{3} = 64$. Which line is the same fact in logarithmic form?`, opts: O([r`\log_{4} 64 = 3`, r`\log_{3} 64 = 4`, r`\log_{64} 4 = 3`, r`\log_{4} 3 = 64`]), key: 'a', sol: r`In $a^{x} = N$ the base is $a$, the exponent is $x$ and the number is $N$; the logarithmic form is $\log_{a} N = x$. Here $a = 4$, $x = 3$, $N = 64$, so the line is $\log_{4} 64 = 3$. The others swap the base, the exponent and the number.`, d: 1, c: 'recall', t: [1], time: 45 }), (C) => { C.assert(powEq(4, 3, 64) && isLog(4, 64, [3, 1]), '4^3 = 64 and log_4 64 = 3'); C.which([r`\log_{4} 64 = 3`, r`\log_{3} 64 = 4`, r`\log_{64} 4 = 3`, r`\log_{4} 3 = 64`], `\\log_{4} 64 = ${LT(4, 64)}`); });

Q('m02', mk.mcq({ stem: r`Savita wants $\log_{b} 49 = 2$ to hold for a base $b$ that is positive and not $1$. What must $b$ be?`, opts: O(['7', '-7', '98', r`\dfrac{49}{2}`]), key: 'a', sol: r`Converting, $b^{2} = 49$, so $b = 7$ or $b = -7$. A base must be positive, so $b = 7$. Check: $7^{2} = 49$.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { C.assert(powEq(7, 2, 49) && !powEq(98, 2, 49), '7^2 = 49'); pick(C, [[7, 1], [-7, 1], [98, 1], [49, 2]], ([n, d]) => n / d > 0 && n / d !== 1 && powEq([n, d], 2, 49)); });

Q('m03', mk.mcq({ stem: r`A patch of imagined moss covers $3^{t}$ square centimetres after $t$ weeks. After how many weeks does it cover $243$ square centimetres?`, opts: O(['4', '5', '6', '81']), key: 'b', sol: r`We need $3^{t} = 243$. In logarithmic form $t = \log_{3} 243$. Since $3^{5} = 243$, $t = 5$ weeks.`, d: 2, c: 'application', t: [1], time: 60 }), (C) => { C.assert(powEq(3, 5, 243), '3^5 = 243'); C.which(['4', '5', '6', '81'], LT(3, 243)); });

Q('m04', mk.mcq({ stem: r`An imagined signal meter shows the number $\log_{2} r$ on its dial, where $r$ is the ratio of the signal to the weakest signal. What does the dial show when $r = \dfrac{1}{64}$?`, opts: O(['-6', '6', r`-\dfrac{1}{6}`, r`\dfrac{1}{6}`]), key: 'a', sol: r`We need $x$ with $2^{x} = \dfrac{1}{64}$. Since $64 = 2^{6}$, $\dfrac{1}{64} = 2^{-6}$, so $x = -6$. The dial reads $-6$.`, d: 2, c: 'application', t: [1], time: 60 }), (C) => { C.assert(powEq(2, -6, [1, 64]), '2^-6 = 1/64'); C.which(['-6', '6', r`-\dfrac{1}{6}`, r`\dfrac{1}{6}`], LT(2, [1, 64])); });

Q('m05', mk.mcq({ stem: r`Which one of these expressions has no real value?`, opts: O([r`\log_{5} 0`, r`\log_{5} 1`, r`\log_{\frac{1}{2}} 8`, r`\log_{10} 0.001`]), key: 'a', sol: r`$\log_{5} 0 = x$ would mean $5^{x} = 0$, but a positive base raised to any real power is positive, so no $x$ exists. The other three are fine: $\log_{5} 1 = 0$, $\log_{\frac{1}{2}} 8 = -3$ and $\log_{10} 0.001 = -3$.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { C.assert(LT(5, 1) === '0' && LT([1, 2], 8) === '-3' && LT(10, [1, 1000]) === '-3', 'the three defined values'); C.assert([-6, -2, 0, 3, 9].every((x) => 5 ** x > 0), '5^x is never 0 (sampled)'); C.key('a'); });

Q('m06', mk.mcq({ stem: r`For every valid base $a$ (that is, $a > 0$ and $a \ne 1$), the value of $\log_{a} a$ is`, opts: O(['1', '0', 'a', r`\dfrac{1}{a}`]), key: 'a', sol: r`$\log_{a} a = x$ means $a^{x} = a = a^{1}$, so $x = 1$ whatever the base. (It is $\log_{a} 1$ that equals $0$.)`, d: 1, c: 'recall', t: [1], time: 45 }), (C) => { C.assert([2, 5, 10, 13, [1, 2]].every((b) => LT(b, b) === '1'), 'log_b b = 1 for several bases'); C.key('a'); });

Q('m07', mk.mcq({ stem: r`A dilute solution has concentration $0.0001$ mole per litre. The common logarithm of this number is`, opts: O(['-4', '-3', '4', r`\dfrac{1}{4}`]), key: 'a', sol: r`Common logarithms use base $10$. $0.0001 = \dfrac{1}{10^{4}} = 10^{-4}$, so $\log 0.0001 = -4$.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { C.assert(powEq(10, -4, [1, 10000]), '10^-4 = 0.0001'); C.which(['-4', '-3', '4', r`\dfrac{1}{4}`], LT(10, [1, 10000])); });

Q('m08', mk.mcq({ stem: r`In the equation $\log_{x} 0.04 = -2$, the base $x$ is`, opts: O(['5', '25', r`\dfrac{1}{5}`, '-5']), key: 'a', sol: r`In exponential form $x^{-2} = 0.04 = \dfrac{1}{25}$, so $x^{2} = 25$ and $x = 5$ or $-5$. The base must be positive, so $x = 5$. Check: $5^{-2} = \dfrac{1}{25}$.`, d: 3, c: 'application', t: [1], time: 75 }), (C) => { pick(C, [[5, 1], [25, 1], [1, 5], [-5, 1]], ([n, d]) => n / d > 0 && n / d !== 1 && powEq([n, d], -2, [4, 100])); });

Q('m09', mk.mcq({ stem: r`Which of these is the product law of logarithms (for positive $m$ and $n$, in any valid base)?`, opts: O([r`\log (mn) = \log m + \log n`, r`\log (mn) = \log m \times \log n`, r`\log (m + n) = \log m \times \log n`, r`\log (mn) = \log m - \log n`]), key: 'a', sol: r`Multiplying inside a logarithm corresponds to adding outside: $\log (mn) = \log m + \log n$. For example $\log 6 = \log 2 + \log 3$. The other lines fail at once for $m = 2$, $n = 3$: $\log 2 \times \log 3 \approx 0.144$ is not $\log 6 \approx 0.778$.`, d: 1, c: 'recall', t: [2], time: 45 }), (C) => { C.assert(law([[1, 2], [1, 3]], 6) && Math.abs(Math.log10(2) * Math.log10(3) - Math.log10(6)) > 0.5 && Math.abs(Math.log10(2) - Math.log10(3) - Math.log10(6)) > 0.5 && Math.abs(Math.log10(5) - Math.log10(2) * Math.log10(3)) > 0.5, 'only the sum form holds for 2 and 3'); C.key('a'); });

Q('m10', mk.mcq({ stem: r`Rohan combines the two readings $\log 45$ and $\log 9$ by working out $\log 45 - \log 9$. He should write the result as the single logarithm`, opts: O([r`\log 5`, r`\log 36`, r`\log 405`, r`\dfrac{\log 45}{\log 9}`]), key: 'a', sol: r`The quotient law gives $\log 45 - \log 9 = \log \dfrac{45}{9} = \log 5$. A difference of logarithms is the logarithm of a quotient, not of a difference ($\log 36$) or of a product ($\log 405$).`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { C.assert(law([[1, 45], [-1, 9]], 5) && !law([[1, 45], [-1, 9]], 36) && !law([[1, 45], [-1, 9]], 405), 'log 45 - log 9 = log 5 only'); C.key('a'); });

Q('m11', mk.mcq({ stem: r`A dial shows the number $\log_{12}\left(12^{0.4}\right) + \log_{12} 1$. What does it show?`, opts: O(['0.4', '4.8', '12.4', '1.4']), key: 'a', sol: r`$\log_{a} a^{x} = x$, so $\log_{12} 12^{0.4} = 0.4$. Also $\log_{12} 1 = 0$. The dial shows $0.4 + 0 = 0.4$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { C.assert(near(Math.log(12 ** 0.4) / Math.log(12), 0.4, 1e-12) && LT(12, 1) === '0', 'log_12 12^0.4 = 0.4, log_12 1 = 0'); C.which(['0.4', '4.8', '12.4', '1.4'], String(0.4 + 0)); });

Q('m12', mk.mcq({ stem: r`If $\log 2 = p$ and $\log 3 = q$, then $\log 72$ can be written as`, opts: O(['3p + 2q', '2p + 3q', '6p + 6q', 'p^{3} q^{2}']), key: 'a', sol: r`$72 = 8 \times 9 = 2^{3} \times 3^{2}$, so $\log 72 = 3\log 2 + 2\log 3 = 3p + 2q$. The powers become multipliers, and the product becomes a sum.`, d: 3, c: 'application', t: [3], time: 75 }), (C) => { C.assert(vEq(vcomb([[3, 2], [2, 3]]), 72) && law([[3, 2], [2, 3]], 72), '72 = 2^3 3^2'); pick(C, [[3, 2], [2, 3], [6, 6], null], (o) => o !== null && law([[o[0], 2], [o[1], 3]], 72)); });

Q('m13', mk.mcq({ stem: r`Meena adds the two readings $\log 5$ and $\log 2000$ on her gauge. The sum is`, opts: O(['4', '3', r`\log 2005`, '10']), key: 'a', sol: r`By the product law $\log 5 + \log 2000 = \log (5 \times 2000) = \log 10000$. Since $10000 = 10^{4}$, the sum is $4$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { C.assert(law([[1, 5], [1, 2000]], 10000) && LT(10, 10000) === '4', 'log 5 + log 2000 = log 10^4 = 4'); C.which(['4', '3', r`\log 2005`, '10'], LT(10, 10000)); });

Q('m14', mk.mcq({ stem: r`The expression $4\log 3 - 2\log 9$ simplifies to`, opts: O(['0', r`\log 3`, r`2\log 3`, r`\log 9`]), key: 'a', sol: r`$4\log 3 = \log 3^{4} = \log 81$ and $2\log 9 = \log 9^{2} = \log 81$. Their difference is $\log 81 - \log 81 = \log 1 = 0$.`, d: 3, c: 'analysis', t: [2], time: 75 }), (C) => { C.assert(law([[4, 3], [-2, 9]], 1) && !law([[4, 3], [-2, 9]], 3) && !law([[4, 3], [-2, 9]], 9), '4 log 3 - 2 log 9 = log 1 = 0'); C.key('a'); });

Q('m15', mk.mcq({ stem: r`The value of $\log_{2} 40 - \log_{2} 5$ is`, opts: O(['3', '5', r`\log_{2} 35`, r`\dfrac{40}{5}`]), key: 'a', sol: r`The quotient law holds in any base: $\log_{2} 40 - \log_{2} 5 = \log_{2} \dfrac{40}{5} = \log_{2} 8 = 3$, because $2^{3} = 8$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { C.assert(law([[1, 40], [-1, 5]], 8, 2) && powEq(2, 3, 8), 'log_2 40 - log_2 5 = log_2 8 = 3'); C.which(['3', '5', r`\log_{2} 35`, r`\dfrac{40}{5}`], LT(2, 8)); });

Q('m16', mk.mcq({ stem: r`For positive $x$, $y$ and $z$, the expression $\log \dfrac{x^{3} y^{2}}{z}$ expands to`, opts: O([r`3\log x + 2\log y - \log z`, r`3\log x - 2\log y - \log z`, r`3\log x + 2\log y + \log z`, r`5\log x \log y - \log z`]), key: 'a', sol: r`Product law: $\log (x^{3} y^{2}) = \log x^{3} + \log y^{2}$; quotient law: subtract $\log z$; power law: $\log x^{3} = 3\log x$ and $\log y^{2} = 2\log y$. So the expansion is $3\log x + 2\log y - \log z$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { pick(C, [[3, 2, -1], [3, -2, -1], [3, 2, 1], null], (cs) => cs !== null && numExp([...cs, 0], [3, 2, -1, 0])); C.key('a'); });

Q('m17', mk.mcq({ stem: r`The expression $\log_{5}(x - 4) + \log_{5}(x + 2)$ has a real value only when`, opts: O([r`x > 4`, r`x > -2`, r`x > 2`, r`x < -2 \text{ or } x > 4`]), key: 'a', sol: r`Each logarithm needs a positive argument: $x - 4 > 0$ gives $x > 4$ and $x + 2 > 0$ gives $x > -2$. Both must hold, and $x > 4$ makes both true. (A value such as $x = -3$ makes both arguments negative and a value such as $x = 0$ makes $x - 4$ negative.)`, d: 3, c: 'analysis', t: [3], time: 75 }), (C) => { const xs = Array.from({ length: 81 }, (_, i) => -10 + i * 0.25); const def = (x) => x - 4 > 0 && x + 2 > 0; const preds = [(x) => x > 4, (x) => x > -2, (x) => x > 2, (x) => x < -2 || x > 4]; pick(C, preds, (p) => xs.every((x) => p(x) === def(x))); });

Q('m18', mk.mcq({ stem: r`The equation $\log_{2} x + \log_{2}(x - 6) = 4$ is solved by`, opts: O(['x = 8', 'x = -2', 'x = 2', 'x = 10']), key: 'a', sol: r`The product law gives $\log_{2}\,x(x - 6) = 4$, so $x(x - 6) = 2^{4} = 16$ and $x^{2} - 6x - 16 = 0$, i.e. $(x - 8)(x + 2) = 0$. Both logarithms need $x > 6$, so $x = -2$ is rejected and $x = 8$ remains. Check: $\log_{2} 8 + \log_{2} 2 = 3 + 1 = 4$.`, d: 3, c: 'application', t: [3], time: 90 }), (C) => { pick(C, [8, -2, 2, 10], (x) => x > 6 && x * (x - 6) === 16); C.assert(logExact(2, 8).n === 3 && logExact(2, 2).n === 1, 'check: 3 + 1 = 4'); });

Q('m19', mk.mcq({ stem: r`Kavya finds $\log 360$ from the given values $\log 2 = 0.3010$ and $\log 5 = 0.6990$. Her lines are:

Line 1: $\log 360 = \log (8 \times 45)$.

Line 2: $= \log 8 + \log 45$.

Line 3: $= 3\log 2 + 2\log 5$.

Line 4: $= 3(0.3010) + 2(0.6990) = 2.301$.

Which is the first line that is wrong?`, opts: ['Line 1', 'Line 2', 'Line 3', 'Line 4'], key: 'c', sol: r`Line 1 is right ($8 \times 45 = 360$) and line 2 is the product law. In line 3, $45 = 3^{2} \times 5$, so $\log 45 = 2\log 3 + \log 5$; the factor $3$ was lost, and $3\log 2 + 2\log 5 = \log 200$, not $\log 360$. Line 4 is correct arithmetic on the wrong line.`, d: 4, c: 'analysis', t: [3], time: 105 }), (C) => { C.assert(8 * 45 === 360 && law([[1, 8], [1, 45]], 360), 'lines 1-2 true'); C.assert(!law([[3, 2], [2, 5]], 360) && law([[3, 2], [2, 5]], 200) && !vEq(vcomb([[3, 2], [2, 5]]), 360), 'line 3 false: it equals log 200'); C.assert(dadd(dmul('3', '0.3010'), dmul('2', '0.6990')) === '2.301', 'line 4 arithmetic is right'); C.which(['Line 1', 'Line 2', 'Line 3', 'Line 4'], 'Line 3'); });

Q('m20', mk.mcq({ stem: r`Using $\log 10 = 1$, which expression equals $\log 0.075$ in terms of $\log 2$ and $\log 3$?`, opts: O([r`\log 3 - 2\log 2 - 1`, r`\log 3 - 3\log 2 - 1`, r`\log 3 + 2\log 2 - 1`, r`\log 3 - 2\log 2 + 1`]), key: 'a', sol: r`$0.075 = \dfrac{3}{40}$ and $40 = 4 \times 10 = 2^{2} \times 10$. Then $\log 0.075 = \log 3 - \log 40 = \log 3 - 2\log 2 - \log 10 = \log 3 - 2\log 2 - 1$.`, d: 4, c: 'application', t: [3], time: 105 }), (C) => { pick(C, [[1, -2, -1], [1, -3, -1], [1, 2, -1], [1, -2, 1]], ([a, b, c]) => law([[a, 3], [b, 2], [c, 10]], [3, 40])); C.assert(Math.abs(0.075 - 3 / 40) < 1e-15, '0.075 = 3/40'); });

Q('m21', mk.mcq({ stem: r`Given $\log 2 = 0.3010$, the number $2^{40}$ has`, opts: ['13 digits', '12 digits', '40 digits', '14 digits'], key: 'a', sol: r`$\log 2^{40} = 40 \times 0.3010 = 12.04$. A number whose common logarithm is between $12$ and $13$ lies between $10^{12}$ and $10^{13}$, so it has $12 + 1 = 13$ digits.`, d: 3, c: 'application', t: [3], time: 75 }), (C) => { const lv = dmul('40', '0.3010'); C.assert(lv === '12.04' && Math.floor(Number(lv)) + 1 === 13 && digitsOf(2, 40) === 13, '40 log 2 = 12.04, so 13 digits (exact power has 13)'); C.which([13, 12, 40, 14].map((n) => `${n} digits`), `${digitsOf(2, 40)} digits`); });

Q('m22', mk.mcq({ stem: r`A calculator is broken, but the given value $\log 3 = 0.4771$ is known. Then $\log 0.027$ is`, opts: ['-1.5687', '1.5687', '-1.4313', '-3.4313'], key: 'a', sol: r`$0.027 = \dfrac{27}{1000}$, so $\log 0.027 = 3\log 3 - \log 1000 = 3(0.4771) - 3 = 1.4313 - 3 = -1.5687$.`, d: 3, c: 'application', t: [3], time: 75 }), (C) => { const v = dsub(dmul('3', '0.4771'), '3'); C.assert(law([[3, 3], [-1, 1000]], [27, 1000]) && v === '-1.5687', 'exact decimal value'); C.which(['-1.5687', '1.5687', '-1.4313', '-3.4313'], v); });

// =============================================================== Assertion-reason (keys c a b d c)
Q('ar1', mk.ar({ a: r`$\log_{7} 1 = 0$.`, r: r`$7^{0} = 1$.`, key: 'c', sol: r`$\log_{7} 1 = x$ means $7^{x} = 1$, and $7^{0} = 1$ gives $x = 0$. So A is true, R is true, and R is exactly the reason. Option (c).`, d: 1, c: 'understanding', t: [1] }), (C) => { C.assert(powEq(7, 0, 1) && LT(7, 1) === '0', 'A and R true'); C.key('c'); });
Q('ar2', mk.ar({ a: r`$\log 6 = \log 2 + \log 3$.`, r: r`$\log (m + n) = \log m + \log n$ for all positive numbers $m$ and $n$.`, key: 'a', sol: r`$\log 6 = \log (2 \times 3) = \log 2 + \log 3$, so A is true. R is false: the product law concerns $\log (mn)$, not $\log (m + n)$. For $m = n = 1$, $\log 2 \approx 0.301$ but $\log 1 + \log 1 = 0$. Option (a).`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(law([[1, 2], [1, 3]], 6) && Math.abs(Math.log10(1 + 1) - (Math.log10(1) + Math.log10(1))) > 0.3, 'A true; R fails at m = n = 1'); C.key('a'); });
Q('ar3', mk.ar({ a: r`$\log_{5}(-25) = 2$.`, r: r`A positive base raised to any real power gives a positive number, so the logarithm of a negative number is not defined.`, key: 'b', sol: r`$\log_{5}(-25) = 2$ would need a power of $5$ to be negative, but $5^{2} = 25$; in fact no power of $5$ is negative, so $\log_{5}(-25)$ does not exist. A is false and R is true. Option (b).`, d: 2, c: 'analysis', t: [1] }), (C) => { C.assert(powEq(5, 2, 25) && !powEq(5, 2, [-25, 1]) && [-4, -1, 0, 1, 2, 3].every((x) => 5 ** x > 0), 'A false, R true'); C.key('b'); });
Q('ar4', mk.ar({ a: r`$\log 1000 - \log 10 = 2$.`, r: r`$\log 100 = 2$.`, key: 'd', sol: r`$\log 1000 - \log 10 = 3 - 1 = 2$, so A is true, and R is also true since $100 = 10^{2}$. But R is only a value; the reason for A is the quotient law, $\log 1000 - \log 10 = \log \dfrac{1000}{10} = \log 100$, which R does not state. Option (d).`, d: 3, c: 'analysis', t: [3] }), (C) => { C.assert(law([[1, 1000], [-1, 10]], 100) && LT(10, 100) === '2' && LT(10, 1000) === '3' && LT(10, 10) === '1', 'A and R true'); C.key('d'); });
Q('ar5', mk.ar({ a: r`$\log 5 + \log 20 = 2$.`, r: r`For positive $m$ and $n$, $\log m + \log n = \log (mn)$.`, key: 'c', sol: r`By R, $\log 5 + \log 20 = \log 100 = 2$, so A is true, and R is the law that gives it. Option (c).`, d: 2, c: 'application', t: [2] }), (C) => { C.assert(law([[1, 5], [1, 20]], 100) && LT(10, 100) === '2', 'A true by the product law'); C.key('c'); });

// =============================================================== True / false
Q('tf1', mk.tf({ stem: r`Because $(-3)^{2} = 9$, Nikhil says that $\log_{-3} 9 = 2$ is a correct statement.`, key: 'f', sol: r`A base must be positive (and not $1$). A negative base does not give a real power for every exponent, for example $(-3)^{\frac{1}{2}}$ is not real, so the logarithm is not defined for such a base.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert((-3) ** 2 === 9 && Number.isNaN((-3) ** 0.5), '(-3)^2 = 9 but (-3)^(1/2) is not real'); C.key('f'); });
Q('tf2', mk.tf({ stem: r`Since $14 = 7 \times 2$, it follows that $\log 14 = \log 7 \times \log 2$.`, key: 'f', sol: r`The product law turns a product into a sum: $\log 14 = \log 7 + \log 2 \approx 0.845 + 0.301 = 1.146$. The product $\log 7 \times \log 2 \approx 0.254$ is quite different.`, d: 1, c: 'understanding', t: [2] }), (C) => { C.assert(law([[1, 7], [1, 2]], 14) && Math.abs(lg(7) * lg(2) - lg(14)) > 0.5, 'sum, not product'); C.key('f'); });
Q('tf3', mk.tf({ stem: r`Dev says that $\log \dfrac{1}{8} = -3\log 2$.`, key: 't', sol: r`$\dfrac{1}{8} = 2^{-3}$, so by the power law $\log \dfrac{1}{8} = \log 2^{-3} = -3\log 2$. (Also $\log \dfrac{1}{8} = \log 1 - \log 8 = -3\log 2$.)`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(law([[-3, 2]], [1, 8]) && law([[1, 1], [-3, 2]], [1, 8]), 'log(1/8) = -3 log 2'); C.key('t'); });
Q('tf4', mk.tf({ stem: r`The value of $\log_{b} 1$ is $0$ whichever valid base $b$ is used.`, key: 't', sol: r`$\log_{b} 1 = x$ means $b^{x} = 1$, and $b^{0} = 1$ for every positive $b$, so $x = 0$ for every valid base.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert([2, 3, 10, 17, [3, 5]].every((b) => LT(b, 1) === '0'), 'log_b 1 = 0 for several bases'); C.key('t'); });
Q('tf5', mk.tf({ stem: r`Because $x(x - 2) = 3$ has the roots $x = 3$ and $x = -1$, both numbers solve $\log_{3} x + \log_{3}(x - 2) = 1$.`, key: 'f', sol: r`The equation needs $x > 0$ and $x - 2 > 0$, that is $x > 2$. So $x = -1$ is rejected (its logarithms are not defined) and only $x = 3$ is a solution. Check: $\log_{3} 3 + \log_{3} 1 = 1 + 0 = 1$.`, d: 3, c: 'analysis', t: [3] }), (C) => { const ok = (x) => x > 0 && x - 2 > 0 && x * (x - 2) === 3; C.assert(ok(3) && !ok(-1) && 3 * 1 === 3 && -1 * -3 === 3, 'only 3 satisfies the equation and its domain'); C.key('f'); });

// =============================================================== Fill in the blank
Q('f1', mk.fill({ stem: r`If $\log_{2} x = -5$, then $x = $ ______ (give a fraction or a decimal).`, acc: [['1/32', '0.03125']], sol: r`$x = 2^{-5} = \dfrac{1}{2^{5}} = \dfrac{1}{32} = 0.03125$.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(powEq(2, -5, [1, 32]), '2^-5 = 1/32'); C.blank(1 / 32); });
Q('f2', mk.fill({ stem: r`The logarithm of $1$ to any valid base is ______.`, acc: [['0']], sol: r`$b^{0} = 1$ for every valid base $b$, so $\log_{b} 1 = 0$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert([2, 6, 10, 25].every((b) => LT(b, 1) === '0'), 'log_b 1 = 0'); C.blank(0); });
Q('f3', mk.fill({ stem: r`Given that $\log 4 = 0.6021$, the value of $\log 400$ is ______.`, acc: [['2.6021']], sol: r`$\log 400 = \log (4 \times 100) = \log 4 + \log 100 = 0.6021 + 2 = 2.6021$.`, d: 2, c: 'application', t: [2] }), (C) => { C.assert(dadd('0.6021', '2') === '2.6021' && LT(10, 100) === '2' && law([[1, 4], [2, 10]], 400), 'log 400 = 2.6021'); C.blank(2.6021); });
Q('f4', mk.fill({ stem: r`$\log_{6} 4 + \log_{6} 9 = $ ______.`, acc: [['2']], sol: r`$\log_{6} 4 + \log_{6} 9 = \log_{6} 36 = 2$, because $6^{2} = 36$.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(law([[1, 4], [1, 9]], 36, 6) && LT(6, 36) === '2', 'log_6 36 = 2'); C.blank(2); });
Q('f5', mk.fill({ stem: r`$\log 2 + \log 5 + \log 30 - \log 3 = $ ______.`, acc: [['2']], sol: r`$\log \dfrac{2 \times 5 \times 30}{3} = \log 100 = 2$.`, d: 3, c: 'application', t: [3] }), (C) => { C.assert(law([[1, 2], [1, 5], [1, 30], [-1, 3]], 100) && LT(10, 100) === '2' && (2 * 5 * 30) / 3 === 100, 'the product is 100'); C.blank(2); });

// =============================================================== Numerical
Q('n1', mk.num({ stem: r`A rumour in an imagined village is passed on so that the number of people who know it is $3^{h}$ after $h$ hours. After how many hours do exactly $729$ people know it?`, value: 6, sol: r`$3^{h} = 729$, so $h = \log_{3} 729$. Since $729 = 3^{6}$, $h = 6$ hours.`, scheme: [['Write h = log base 3 of 729', 0.5], ['3^6 = 729, so h = 6', 0.5]], d: 2, c: 'application', t: [1], time: 60 }), (C) => { C.assert(powEq(3, 6, 729), '3^6 = 729'); C.val(Number(LT(3, 729))); });
Q('n2', mk.num({ stem: r`Using $\log 2 = 0.3010$, find the number of digits in $2^{50}$.`, value: 16, sol: r`$\log 2^{50} = 50 \times 0.3010 = 15.05$. A number with common logarithm between $15$ and $16$ has $15 + 1 = 16$ digits.`, scheme: [['50 times 0.3010 = 15.05', 0.5], ['15 + 1 = 16 digits', 0.5]], d: 3, c: 'application', t: [3], time: 75 }), (C) => { const lv = dmul('50', '0.3010'); C.assert(lv === '15.05', '50 log 2 = 15.05'); C.val(Math.floor(Number(lv)) + 1); C.assert(digitsOf(2, 50) === 16, '2^50 really has 16 digits'); });
Q('n3', mk.num({ stem: r`The base $x$ of a logarithm satisfies $\log_{x} 343 = \dfrac{3}{2}$. Find $x$.`, value: 49, sol: r`In exponential form $x^{\frac{3}{2}} = 343 = 7^{3}$. Raising both sides to the power $\dfrac{2}{3}$ gives $x = 7^{2} = 49$. Check: $49^{\frac{3}{2}} = 7^{3} = 343$.`, scheme: [['x^(3/2) = 343', 0.5], ['x = 7^2 = 49', 0.5]], d: 3, c: 'application', t: [1], time: 90 }), (C) => { C.assert(powEq(49, [3, 2], 343) && !powEq(7, [3, 2], 343), '49^(3/2) = 343'); C.val(49); });
Q('n4', mk.num({ stem: r`An imagined algae film covers $3$ square centimetres at noon on day $0$ and its area doubles every day, so after $n$ days it covers $3 \times 2^{n}$ square centimetres. Using $\log 2 = 0.3010$ and $\log 3 = 0.4771$, find the least whole number of days after which the area exceeds $2000$ square centimetres.`, value: 10, marks: 2, sol: r`We need $3 \times 2^{n} > 2000$, so $2^{n} > \dfrac{2000}{3}$. Taking logarithms, $n \log 2 > \log 2000 - \log 3 = 3.3010 - 0.4771 = 2.8239$. Then $n > \dfrac{2.8239}{0.3010} = 9.38\ldots$, so the least whole number is $n = 10$. Check: $3 \times 2^{9} = 1536 < 2000 < 3072 = 3 \times 2^{10}$.`, scheme: [['Set up 3 times 2^n greater than 2000 and take logarithms: n log 2 greater than log 2000 minus log 3', 1], ['2.8239 divided by 0.3010 = 9.38, so n = 10', 1]], d: 4, c: 'application', t: [3], time: 150 }), (C) => { const l2000 = dadd(dmul('3', '1'), '0.3010'); const rhs = dsub(l2000, '0.4771'); C.assert(l2000 === '3.3010' || l2000 === '3.301', 'log 2000 = 3 + log 2'); C.assert(rhs === '2.8239', '2.8239'); const q = Number(rhs) / 0.301; C.assert(q > 9.38 && q < 9.39 && Math.ceil(q) === 10, 'n > 9.38'); const first = (() => { let n = 0; while (3 * 2 ** n <= 2000) n++; return n; })(); C.val(first); C.assert(3 * 2 ** 9 === 1536 && 3 * 2 ** 10 === 3072, 'bracketing check'); });
Q('n5', mk.num({ stem: r`Given $\log 2 = 0.3010$ and $\log 3 = 0.4771$, find the value of $\log 144$.`, value: 2.1582, sol: r`$144 = 2^{4} \times 3^{2}$, so $\log 144 = 4\log 2 + 2\log 3 = 4(0.3010) + 2(0.4771) = 1.2040 + 0.9542 = 2.1582$.`, scheme: [['144 = 2^4 times 3^2 and the laws', 0.5], ['4(0.3010) + 2(0.4771) = 2.1582', 0.5]], d: 2, c: 'understanding', t: [3], time: 75 }), (C) => { C.assert(vEq(vcomb([[4, 2], [2, 3]]), 144) && law([[4, 2], [2, 3]], 144), '144 = 2^4 3^2'); C.val(Number(fromGiven([[4, 2], [2, 3]]))); });
Q('n6', mk.num({ stem: r`Solve $\log_{2}(3x - 2) - \log_{2}(x - 1) = 2$ for $x$.`, value: 2, marks: 2, sol: r`The quotient law gives $\log_{2}\dfrac{3x - 2}{x - 1} = 2$, so $\dfrac{3x - 2}{x - 1} = 2^{2} = 4$. Then $3x - 2 = 4x - 4$, so $x = 2$. Domain: $3x - 2 = 4 > 0$ and $x - 1 = 1 > 0$, so $x = 2$ is valid. Check: $\log_{2} 4 - \log_{2} 1 = 2 - 0 = 2$.`, scheme: [['Quotient law and conversion: (3x - 2)/(x - 1) = 4', 1], ['x = 2, with the domain check', 1]], d: 3, c: 'application', t: [3], time: 120 }), (C) => { const x = 2; C.assert(3 * x - 2 === 4 * (x - 1) && 3 * x - 2 > 0 && x - 1 > 0, 'x = 2 solves and is in the domain'); C.assert(LT(2, 4) === '2' && LT(2, 1) === '0', 'check: 2 - 0 = 2'); C.val(x); });
Q('n7', mk.num({ stem: r`An imagined acidity score for a sample is defined as $-\log c$, where $c$ is the concentration in mole per litre. A sample has $c = 4 \times 10^{-6}$. Using $\log 2 = 0.3010$, find its score.`, value: 5.398, marks: 2, sol: r`$\log c = \log 4 + \log 10^{-6} = 2\log 2 - 6 = 0.6020 - 6 = -5.398$. So the score is $-\log c = 5.398$.`, scheme: [['log c = 2 log 2 - 6 = -5.398', 1], ['Score = 5.398', 1]], d: 3, c: 'application', t: [3, 1], time: 120 }), (C) => { const lc = dsub(fromGiven([[2, 2]]), '6'); C.assert(lc === '-5.398' && law([[2, 2], [-6, 10]], [4, 1000000]), 'log c = -5.398'); C.val(-Number(lc)); });

// =============================================================== Short answer, 2 marks
Q('s201', mk.short({ marks: 2, stem: r`A lab technician records two facts: $10^{-2} = 0.01$ and $64^{\frac{1}{3}} = 4$. Write each fact in logarithmic form.`, model: r`$10^{-2} = 0.01$ gives $\log_{10} 0.01 = -2$, and $64^{\frac{1}{3}} = 4$ gives $\log_{64} 4 = \dfrac{1}{3}$.`, sol: r`Use $a^{x} = N \iff \log_{a} N = x$: the base stays the base, the exponent becomes the value of the logarithm, and the result of the power becomes the number.`, scheme: [['log base 10 of 0.01 = -2', 1], ['log base 64 of 4 = 1/3', 1]], d: 1, c: 'recall', t: [1], time: 90 }), (C) => { C.assert(powEq(10, -2, [1, 100]) && powEq(64, [1, 3], 4) && isLog(10, [1, 100], [-2, 1]) && isLog(64, 4, [1, 3]), 'both facts hold in both forms'); C.model(['-2', '4', '64']); });
Q('s202', mk.short({ marks: 2, stem: r`A fractal sketch has $\log_{x} 0.0625 = 4$. Find the positive base $x$.`, model: r`In exponential form $x^{4} = 0.0625 = \dfrac{1}{16}$. Since $\left(\dfrac{1}{2}\right)^{4} = \dfrac{1}{16}$ and the base must be positive, $x = \dfrac{1}{2}$.`, sol: r`$x^{4} = \dfrac{1}{16}$ gives $x = \pm\dfrac{1}{2}$; only the positive value is allowed as a base. Check: $\left(\dfrac{1}{2}\right)^{4} = \dfrac{1}{16} = 0.0625$.`, scheme: [['Exponential form x^4 = 1/16', 1], ['x = 1/2 (positive base)', 1]], d: 2, c: 'application', t: [1], time: 90 }), (C) => { C.assert(powEq([1, 2], 4, [625, 10000]) && !powEq([1, 3], 4, [625, 10000]) && 0.0625 === 1 / 16, '(1/2)^4 = 0.0625'); C.assert(logExact([1, 2], [1, 16]).n === 4, 'log_(1/2) (1/16) = 4'); C.model(['16', '2']); });
Q('s203', mk.short({ marks: 2, stem: r`Write $\log 6 + \log 35 - \log 21$ as a single logarithm and state its value.`, model: r`$\log 6 + \log 35 - \log 21 = \log \dfrac{6 \times 35}{21} = \log 10 = 1$.`, sol: r`Product law for the sum, quotient law for the difference: $\dfrac{6 \times 35}{21} = \dfrac{210}{21} = 10$, and $\log 10 = 1$.`, scheme: [['Single logarithm log(6 times 35 over 21) = log 10', 1], ['Value 1', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { C.assert(law([[1, 6], [1, 35], [-1, 21]], 10) && LT(10, 10) === '1' && (6 * 35) / 21 === 10, 'log 10 = 1'); C.model(['10', '1']); });
Q('s204', mk.short({ marks: 2, stem: r`Given $\log 5 = 0.6990$, find $\log 125$.`, model: r`$125 = 5^{3}$, so $\log 125 = 3\log 5 = 3(0.6990) = 2.097$.`, sol: r`By the power law $\log 5^{3} = 3\log 5$. Then $3 \times 0.6990 = 2.0970 = 2.097$.`, scheme: [['125 = 5^3 and log 125 = 3 log 5', 1], ['3 times 0.6990 = 2.097', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { C.assert(vEq(vcomb([[3, 5]]), 125) && law([[3, 5]], 125) && fromGiven([[3, 5]]) === '2.097', 'log 125 = 2.097 from the given'); C.model([2.097, 125]); });
Q('s205', mk.short({ marks: 2, stem: r`Expand $\log \dfrac{p^{5}\sqrt{q}}{r^{3}}$ in terms of $\log p$, $\log q$ and $\log r$, where $p$, $q$, $r$ are positive.`, model: r`$\log \dfrac{p^{5}\sqrt{q}}{r^{3}} = \log p^{5} + \log q^{\frac{1}{2}} - \log r^{3} = 5\log p + \dfrac{1}{2}\log q - 3\log r$.`, sol: r`The product and quotient laws split the expression into $\log p^{5} + \log \sqrt{q} - \log r^{3}$, and the power law (with $\sqrt{q} = q^{\frac{1}{2}}$) turns each power into a multiplier.`, scheme: [['Split with the product and quotient laws', 1], ['Powers become multipliers: 5 log p + (1/2) log q - 3 log r', 1]], d: 2, c: 'understanding', t: [3], time: 90 }), (C) => { C.assert(numExp([5, 0.5, -3, 0], [5, 0.5, -3, 0]) && !numExp([5, 0.5, 3, 0], [5, 0.5, -3, 0]), 'expansion verified at three points'); C.model(['5', '3']); });
Q('s206', mk.short({ marks: 2, stem: r`Write $2\log 3 + \dfrac{1}{2}\log 16 - \log 6$ as a single logarithm.`, model: r`$2\log 3 = \log 9$ and $\dfrac{1}{2}\log 16 = \log 16^{\frac{1}{2}} = \log 4$. So the expression is $\log \dfrac{9 \times 4}{6} = \log 6$.`, sol: r`Power law first: $\log 9 + \log 4 - \log 6$. Then product and quotient: $\log \dfrac{36}{6} = \log 6$.`, scheme: [['Power law: log 9 + log 4 - log 6', 1], ['Combine: log 6', 1]], d: 3, c: 'application', t: [3], time: 100 }), (C) => { C.assert(law([[2, 3], [[1, 2], 16], [-1, 6]], 6) && Math.sqrt(16) === 4 && (9 * 4) / 6 === 6, 'result log 6'); C.model(['9', '4', '6']); });
Q('s207', mk.short({ marks: 2, stem: r`For which values of $x$ is the expression $\log_{4}(x - 3) + \log_{4}(10 - x)$ defined?`, model: r`Both arguments must be positive: $x - 3 > 0$ gives $x > 3$, and $10 - x > 0$ gives $x < 10$. So the expression is defined for $3 < x < 10$.`, sol: r`A logarithm needs a positive argument, so the two conditions $x > 3$ and $x < 10$ must hold together.`, scheme: [['x - 3 > 0 and 10 - x > 0', 1], ['3 < x < 10', 1]], d: 3, c: 'analysis', t: [3], time: 100 }), (C) => { const xs = Array.from({ length: 261 }, (_, i) => -5 + i * 0.1); const def = (x) => x - 3 > 0 && 10 - x > 0; C.assert(xs.every((x) => def(x) === (Math.round(x * 10) > 30 && Math.round(x * 10) < 100)), 'defined exactly for 3 < x < 10'); C.model(['3', '10']); });
Q('s208', mk.short({ marks: 2, stem: r`Show that $\log 50 - \log 2 = 2\log 5$.`, model: r`$\log 50 - \log 2 = \log \dfrac{50}{2} = \log 25 = \log 5^{2} = 2\log 5$.`, sol: r`The quotient law gives $\log 25$, and $25 = 5^{2}$, so the power law gives $2\log 5$.`, scheme: [['Quotient law: log 25', 1], ['25 = 5^2, so 2 log 5', 1]], d: 2, c: 'understanding', t: [3], time: 90 }), (C) => { C.assert(law([[1, 50], [-1, 2]], 25) && law([[1, 50], [-1, 2]], 25) && vEq(vcomb([[1, 50], [-1, 2]]), vcomb([[2, 5]])), 'identity holds exactly'); C.model(['25', '50']); });

// =============================================================== Short answer, 3 marks
Q('s301', mk.short({ marks: 3, stem: r`(i) Write $16^{\frac{1}{4}} = 2$ in logarithmic form. (ii) Find the value of $\log_{\frac{1}{2}} 32$. (iii) Find $x$ if $\log_{5} x = -2$.`, model: r`(i) $\log_{16} 2 = \dfrac{1}{4}$.

(ii) Let $\log_{\frac{1}{2}} 32 = y$. Then $\left(\dfrac{1}{2}\right)^{y} = 32 = 2^{5}$, so $2^{-y} = 2^{5}$ and $y = -5$.

(iii) $x = 5^{-2} = \dfrac{1}{25}$.`, sol: r`Each part is one conversion between $a^{x} = N$ and $\log_{a} N = x$. In (ii) write both sides as powers of $2$ and compare exponents.`, scheme: [['(i) log base 16 of 2 = 1/4', 1], ['(ii) (1/2)^y = 2^5 gives y = -5', 1], ['(iii) x = 5^(-2) = 1/25', 1]], d: 2, c: 'application', t: [1], time: 150 }), (C) => { C.assert(powEq(16, [1, 4], 2) && LT([1, 2], 32) === '-5' && powEq(5, -2, [1, 25]), 'three conversions'); C.model(['-5', '25', '16']); });
Q('s302', mk.short({ marks: 3, stem: r`If $\log 2 = a$ and $\log 3 = b$, express $\log 0.72$ in terms of $a$ and $b$.`, model: r`$0.72 = \dfrac{72}{100} = \dfrac{2^{3} \times 3^{2}}{10^{2}}$. So $\log 0.72 = 3\log 2 + 2\log 3 - 2\log 10 = 3a + 2b - 2$.`, sol: r`Write $0.72 = \dfrac{72}{100}$, factorise $72 = 2^{3} \times 3^{2}$, and use $\log 10 = 1$, so that $\log 100 = 2$.`, scheme: [['0.72 = 72/100 = 2^3 times 3^2 over 10^2', 1], ['Laws: 3 log 2 + 2 log 3 - 2 log 10', 1], ['3a + 2b - 2', 1]], d: 3, c: 'application', t: [3], time: 150 }), (C) => { C.assert(law([[3, 2], [2, 3], [-2, 10]], [18, 25]) && 72 / 100 === 0.72 && 8 * 9 === 72, 'log 0.72 = 3a + 2b - 2'); C.model(['72', '2']); });
Q('s303', mk.short({ marks: 3, stem: r`Given $\log 2 = 0.3010$, $\log 3 = 0.4771$ and $\log 7 = 0.8451$, find (i) $\log 84$ and (ii) $\log 2.1$.`, model: r`(i) $84 = 2^{2} \times 3 \times 7$, so $\log 84 = 2(0.3010) + 0.4771 + 0.8451 = 0.6020 + 0.4771 + 0.8451 = 1.9242$.

(ii) $2.1 = \dfrac{21}{10}$, so $\log 2.1 = \log 3 + \log 7 - \log 10 = 0.4771 + 0.8451 - 1 = 0.3222$.`, sol: r`Factorise $84$ over the primes $2, 3, 7$, and write $2.1$ as $\dfrac{3 \times 7}{10}$ with $\log 10 = 1$.`, scheme: [['84 = 2^2 times 3 times 7', 1], ['log 84 = 1.9242', 1], ['log 2.1 = 0.4771 + 0.8451 - 1 = 0.3222', 1]], d: 3, c: 'application', t: [3], time: 150 }), (C) => { C.assert(fromGiven([[2, 2], [1, 3], [1, 7]]) === '1.9242' && vEq(vcomb([[2, 2], [1, 3], [1, 7]]), 84), 'log 84 = 1.9242'); C.assert(dsub(fromGiven([[1, 3], [1, 7]]), '1') === '0.3222' && law([[1, 3], [1, 7], [-1, 10]], [21, 10]), 'log 2.1 = 0.3222'); C.model([1.9242, 0.3222, 84]); });
Q('s304', mk.short({ marks: 3, stem: r`Solve $\log_{6}(x + 2) + \log_{6}(x - 3) = 1$ and state clearly why any value you reject is rejected.`, model: r`$\log_{6}(x + 2)(x - 3) = 1$, so $(x + 2)(x - 3) = 6$. Then $x^{2} - x - 6 = 6$, so $x^{2} - x - 12 = 0$ and $(x - 4)(x + 3) = 0$. Since $x - 3 > 0$ is needed, $x > 3$: $x = -3$ is rejected because $x + 2 = -1$ and $x - 3 = -6$ are negative, and $x = 4$ is accepted.`, sol: r`Check: $\log_{6} 6 + \log_{6} 1 = 1 + 0 = 1$.`, scheme: [['Product law and conversion: (x + 2)(x - 3) = 6', 1], ['x^2 - x - 12 = 0, so x = 4 or x = -3', 1], ['Domain x > 3: reject -3, keep 4', 1]], d: 3, c: 'application', t: [3], time: 150 }), (C) => { const ok = (x) => x + 2 > 0 && x - 3 > 0 && (x + 2) * (x - 3) === 6; C.assert(ok(4) && !ok(-3) && (-3 + 2) * (-3 - 3) === 6 && 4 * 4 - 4 - 12 === 0, 'only 4'); C.assert(LT(6, 6) === '1' && LT(6, 1) === '0', 'check 1 + 0'); C.model(['6', '4', '-3']); });
Q('s305', mk.short({ marks: 3, stem: r`Prove that $\log \dfrac{a}{b} + \log \dfrac{b}{c} + \log \dfrac{c}{a} = 0$ for positive $a$, $b$ and $c$.`, model: r`By the product law, $\log \dfrac{a}{b} + \log \dfrac{b}{c} + \log \dfrac{c}{a} = \log \left(\dfrac{a}{b} \times \dfrac{b}{c} \times \dfrac{c}{a}\right)$. The product of the three fractions is $\dfrac{abc}{abc} = 1$, so the sum is $\log 1 = 0$.`, sol: r`The factors $a$, $b$, $c$ cancel in pairs, leaving $1$; and $\log 1 = 0$ in every base.`, scheme: [['Combine with the product law', 1], ['The product of the fractions is 1', 1], ['log 1 = 0', 1]], d: 3, c: 'analysis', t: [3], time: 150 }), (C) => { C.assert([[2, 5, 7], [3, 11, 13], [9, 4, 25]].every(([a, b, c]) => vEq(vcomb([[1, [a, b]], [1, [b, c]], [1, [c, a]]]), 1) && law([[1, [a, b]], [1, [b, c]], [1, [c, a]]], 1)), 'identity holds for three triples'); C.model(['1', '0']); });
Q('s306', mk.short({ marks: 3, stem: r`Use $\log 5 = 1 - \log 2$ to express $\log 250$ in terms of $\log 2$ only.`, model: r`$250 = 2 \times 5^{3}$, so $\log 250 = \log 2 + 3\log 5 = \log 2 + 3(1 - \log 2) = \log 2 + 3 - 3\log 2 = 3 - 2\log 2$.`, sol: r`The relation $\log 5 = 1 - \log 2$ comes from $\log 5 + \log 2 = \log 10 = 1$.`, scheme: [['250 = 2 times 5^3 and the laws: log 2 + 3 log 5', 1], ['Substitute log 5 = 1 - log 2', 1], ['3 - 2 log 2', 1]], d: 4, c: 'application', t: [3], time: 150 }), (C) => { C.assert(law([[1, 2], [1, 5]], 10) && vEq(vcomb([[1, 2], [3, 5]]), 250) && law([[3, 10], [-2, 2]], 250), 'log 250 = 3 - 2 log 2'); C.model(['250', '3']); });

// =============================================================== Long answer, 10 marks (3 + 3 + 4)
Q('l01', mk.long({ marks: 10, stem: r`(a) Work out $125^{\frac{1}{3}}$ and use it to check that $125^{\frac{2}{3}} = 25$; then write this fact in logarithmic form. [3]

(b) Find the value of $\log_{\frac{1}{4}} 32$. [3]

(c) Find the base $x$ if $\log_{x} 0.001 = -3$, and hence evaluate $\log_{x} x^{5} + \log_{x} 1$. [4]`, model: r`(a) $125^{\frac{1}{3}} = 5$ because $5^{3} = 125$. Then $125^{\frac{2}{3}} = 5^{2} = 25$, so the fact is true. In logarithmic form, $\log_{125} 25 = \dfrac{2}{3}$.

(b) Let $\log_{\frac{1}{4}} 32 = y$. Then $\left(\dfrac{1}{4}\right)^{y} = 32$, that is $2^{-2y} = 2^{5}$. So $-2y = 5$ and $y = -\dfrac{5}{2}$.

(c) $x^{-3} = 0.001 = \dfrac{1}{1000}$, so $x^{3} = 1000$ and $x = 10$ (a base is positive). Then $\log_{10} 10^{5} = 5$ and $\log_{10} 1 = 0$, so the value is $5 + 0 = 5$.`, sol: r`Convert each statement between $a^{x} = N$ and $\log_{a} N = x$, and write both sides over a common prime base when the base is a fraction.`, scheme: [['(a) cube root 5, then 5^2 = 25', 2], ['(a) log base 125 of 25 = 2/3', 1], ['(b) (1/4)^y = 32 rewritten as 2^(-2y) = 2^5', 2], ['(b) y = -5/2', 1], ['(c) x^(-3) = 1/1000, so x = 10', 2], ['(c) log_x x^5 = 5, log_x 1 = 0, total 5', 2]], d: 3, c: 'application', t: [1], time: 420 }), (C) => { C.assert(powEq(125, [1, 3], 5) && powEq(125, [2, 3], 25) && isLog(125, 25, [2, 3]), '(a)'); C.assert(LT([1, 4], 32) === r`-\dfrac{5}{2}` && powEq([1, 4], [-5, 2], 32), '(b) -5/2'); C.assert(powEq(10, -3, [1, 1000]) && LT(10, 100000) === '5' && LT(10, 1) === '0', '(c) x = 10, value 5'); C.model(['125', '25', '5', '10']); });
Q('l02', mk.long({ marks: 10, stem: r`(a) Let $\log_{a} m = x$ and $\log_{a} n = y$. Prove that $\log_{a}(mn) = x + y$. [3]

(b) Prove that $\log_{a} m^{p} = p\log_{a} m$. [3]

(c) Use the laws to evaluate $\log_{2} 3 + \log_{2} 20 - \log_{2} 15 + 2\log_{2} 6 - \log_{2} 9$. [4]`, model: r`(a) By definition $m = a^{x}$ and $n = a^{y}$. Then $mn = a^{x} \times a^{y} = a^{x + y}$, so in logarithmic form $\log_{a}(mn) = x + y = \log_{a} m + \log_{a} n$.

(b) With $m = a^{x}$, $m^{p} = \left(a^{x}\right)^{p} = a^{px}$, so $\log_{a} m^{p} = px = p\log_{a} m$.

(c) $\log_{2} 3 + \log_{2} 20 - \log_{2} 15 = \log_{2}\dfrac{3 \times 20}{15} = \log_{2} 4 = 2$. Next $2\log_{2} 6 - \log_{2} 9 = \log_{2} 36 - \log_{2} 9 = \log_{2} \dfrac{36}{9} = \log_{2} 4 = 2$. The whole expression is $2 + 2 = 4$.`, sol: r`The two proofs turn the laws of indices into laws of logarithms: $a^{x} a^{y} = a^{x + y}$ and $(a^{x})^{p} = a^{px}$. Part (c) applies the product, quotient and power laws.`, scheme: [['(a) m = a^x and n = a^y', 1], ['(a) mn = a^(x + y)', 1], ['(a) conclusion log(mn) = x + y', 1], ['(b) m^p = a^(px)', 2], ['(b) conclusion p log m', 1], ['(c) first group = log_2 4 = 2', 1], ['(c) 2 log_2 6 = log_2 36 and the quotient with 9 gives log_2 4 = 2', 2], ['(c) total 4', 1]], d: 3, c: 'analysis', t: [2], time: 450 }), (C) => { const a = 3, m = 5, n = 7, p = 3.5; const L = (z) => Math.log(z) / Math.log(a); C.assert(Math.abs(L(m * n) - (L(m) + L(n))) < 1e-12 && Math.abs(L(m ** p) - p * L(m)) < 1e-12, '(a), (b) numerically at a = 3, m = 5, n = 7, p = 3.5'); C.assert(law([[1, 3], [1, 20], [-1, 15]], 4, 2) && law([[2, 6], [-1, 9]], 4, 2) && LT(2, 4) === '2', '(c) two groups of 2'); C.assert(law([[1, 3], [1, 20], [-1, 15], [2, 6], [-1, 9]], 16, 2) && LT(2, 16) === '4', '(c) whole value log_2 16 = 4'); C.model(['4', '36', '15']); });
Q('l03', mk.long({ marks: 10, stem: r`An imagined sound meter scores a sound as $S = 10\log\dfrac{I}{I_{0}}$, where $I$ is its intensity and $I_{0}$ is a fixed reference intensity. Use $\log 2 = 0.3010$.

(a) A sound is $4000$ times as intense as the reference. Find its score. [3]

(b) Another sound scores $53.01$. Find the ratio $\dfrac{I}{I_{0}}$. [3]

(c) Show that doubling the intensity of any sound raises its score by $3.01$, whatever the starting intensity. [4]`, model: r`(a) $\dfrac{I}{I_{0}} = 4000 = 4 \times 10^{3}$, so $\log 4000 = 2\log 2 + 3 = 0.6020 + 3 = 3.6020$. Then $S = 10 \times 3.6020 = 36.02$.

(b) $10\log\dfrac{I}{I_{0}} = 53.01$, so $\log\dfrac{I}{I_{0}} = 5.301 = 5 + 0.3010 = \log 10^{5} + \log 2 = \log (2 \times 10^{5})$. Hence $\dfrac{I}{I_{0}} = 200000$.

(c) Let the original score be $S_{1} = 10\log\dfrac{I}{I_{0}}$. Doubling the intensity gives $S_{2} = 10\log\dfrac{2I}{I_{0}} = 10\left(\log 2 + \log\dfrac{I}{I_{0}}\right)$ by the product law. So $S_{2} - S_{1} = 10\log 2 = 10 \times 0.3010 = 3.01$, which does not depend on $I$.`, sol: r`Parts (a) and (b) use the product law with powers of ten; part (c) shows that multiplying the intensity adds a fixed amount, $10\log 2$, to the score.`, scheme: [['(a) 4000 = 4 times 10^3', 1], ['(a) log 4000 = 3.6020', 1], ['(a) S = 36.02', 1], ['(b) log ratio = 5.301', 1], ['(b) 5.301 = 5 + log 2 = log(2 times 10^5)', 1], ['(b) ratio = 200000', 1], ['(c) S2 = 10 log(2I/I0) = 10(log 2 + log(I/I0))', 2], ['(c) S2 - S1 = 10 log 2', 1], ['(c) 10 times 0.3010 = 3.01, independent of I', 1]], d: 4, c: 'evaluation', t: [3], time: 480 }), (C) => { C.assert(dadd(dmul('2', '0.3010'), '3') === '3.602' && dmul('10', '3.602') === '36.02' && law([[2, 2], [3, 10]], 4000), '(a) 36.02'); C.assert(dmul('10', '0.3010') === '3.01', '(c) 3.01'); C.assert(Math.abs(53.01 / 10 - 5.301) < 1e-12 && dadd('5', '0.3010') === '5.301' && law([[1, 2], [5, 10]], 200000), '(b) ratio 2 x 10^5'); const I = [1.7, 40, 3300]; C.assert(I.every((i) => Math.abs(10 * Math.log10(2 * i) - 10 * Math.log10(i) - 10 * Math.log10(2)) < 1e-12), '(c) numeric, any intensity'); C.model([36.02, 200000, 3.01]); });
Q('l04', mk.long({ marks: 10, stem: r`Solve each equation, checking that every logarithm in it is defined for your answer.

(a) $\log_{5}(3x - 2) = 2$ [3]

(b) $\log_{3}(x + 7) - \log_{3}(x - 1) = 2$ [3]

(c) $\log_{3} x + \log_{3}(x + 6) = 3$ [4]`, model: r`(a) In exponential form $3x - 2 = 5^{2} = 25$, so $3x = 27$ and $x = 9$. Then $3x - 2 = 25 > 0$, so the logarithm is defined.

(b) The quotient law gives $\log_{3}\dfrac{x + 7}{x - 1} = 2$, so $\dfrac{x + 7}{x - 1} = 9$. Then $x + 7 = 9x - 9$, so $16 = 8x$ and $x = 2$. Both arguments, $9$ and $1$, are positive. Check: $\log_{3} 9 - \log_{3} 1 = 2 - 0 = 2$.

(c) $\log_{3}\,x(x + 6) = 3$, so $x(x + 6) = 27$ and $x^{2} + 6x - 27 = 0$, that is $(x + 9)(x - 3) = 0$. We need $x > 0$, so $x = -9$ is rejected (its logarithms are not defined) and $x = 3$. Check: $\log_{3} 3 + \log_{3} 9 = 1 + 2 = 3$.`, sol: r`Convert to exponential form after combining logarithms with the product or quotient law, solve, and reject any root that makes an argument non-positive.`, scheme: [['(a) 3x - 2 = 25', 1], ['(a) x = 9 and the argument 25 is positive', 2], ['(b) quotient law: (x + 7)/(x - 1) = 9', 1], ['(b) x = 2, arguments 9 and 1 positive', 2], ['(c) product law: x(x + 6) = 27', 1], ['(c) (x + 9)(x - 3) = 0', 1], ['(c) reject -9 because x must be positive', 1], ['(c) x = 3 and check', 1]], d: 3, c: 'application', t: [3], time: 480 }), (C) => { C.assert(3 * 9 - 2 === 25 && powEq(5, 2, 25), '(a) x = 9'); const okb = (x) => x + 7 > 0 && x - 1 > 0 && x + 7 === 9 * (x - 1); C.assert(okb(2) && LT(3, 9) === '2' && LT(3, 1) === '0', '(b) x = 2'); const okc = (x) => x > 0 && x + 6 > 0 && x * (x + 6) === 27; C.assert(okc(3) && !okc(-9) && (-9) * (-3) === 27 && LT(3, 3) === '1' && LT(3, 9) === '2', '(c) only x = 3'); C.model(['9', '2', '3', '-9']); });
Q('l05', mk.long({ marks: 10, stem: r`Use $\log 2 = 0.3010$, $\log 3 = 0.4771$ and $\log 5 = 0.6990$.

(a) Find $\log 135$. [3]

(b) Find $\log 0.0375$. [3]

(c) Find the number of digits in $3^{30}$, and state which two powers of $10$ it lies between. [4]`, model: r`(a) $135 = 3^{3} \times 5$, so $\log 135 = 3\log 3 + \log 5 = 3(0.4771) + 0.6990 = 1.4313 + 0.6990 = 2.1303$.

(b) $0.0375 = \dfrac{375}{10000} = \dfrac{3 \times 5^{3}}{10^{4}}$, so $\log 0.0375 = \log 3 + 3\log 5 - 4 = 0.4771 + 2.0970 - 4 = -1.4259$.

(c) $\log 3^{30} = 30\log 3 = 30 \times 0.4771 = 14.313$. Since $14 < 14.313 < 15$, $10^{14} < 3^{30} < 10^{15}$, so $3^{30}$ has $14 + 1 = 15$ digits.`, sol: r`Break each number into the primes $2$, $3$ and $5$ (and powers of $10$ for the decimal point), apply the laws, and for the digit count read off the whole-number part of the logarithm.`, scheme: [['(a) 135 = 3^3 times 5', 1], ['(a) 3 log 3 + log 5', 1], ['(a) 2.1303', 1], ['(b) 0.0375 = 3 times 5^3 over 10^4', 1], ['(b) log 3 + 3 log 5 - 4', 1], ['(b) -1.4259', 1], ['(c) 30 log 3 = 14.313', 1], ['(c) between 14 and 15, so 10^14 < 3^30 < 10^15', 2], ['(c) 15 digits', 1]], d: 4, c: 'application', t: [3], time: 480 }), (C) => { C.assert(fromGiven([[3, 3], [1, 5]]) === '2.1303' && vEq(vcomb([[3, 3], [1, 5]]), 135), '(a) 2.1303'); C.assert(fromGiven([[1, 3], [3, 5]]) !== undefined && dsub(fromGiven([[1, 3], [3, 5]]), '4') === '-1.4259' && law([[1, 3], [3, 5], [-4, 10]], [375, 10000]) && 375 / 10000 === 0.0375, '(b) -1.4259'); const lv = fromGiven([[30, 3]]); C.assert(lv === '14.313' && digitsOf(3, 30) === 15 && 10n ** 14n < 3n ** 30n && 3n ** 30n < 10n ** 15n, '(c) 15 digits'); C.model([2.1303, -1.4259, 14.313, 15]); });
Q('l06', mk.long({ marks: 10, stem: r`(a) Show that $2\log 6 - \log 9 = \log 4$. [3]

(b) Show that $\log\dfrac{9}{10} + \log\dfrac{25}{27} + \log\dfrac{6}{5} = 0$. [3]

(c) The positive numbers $x$ and $y$ satisfy $\log (x + y) = \log x + \log y$. Show that $y = \dfrac{x}{x - 1}$. [4]`, model: r`(a) $2\log 6 = \log 6^{2} = \log 36$, so $2\log 6 - \log 9 = \log \dfrac{36}{9} = \log 4$.

(b) By the product law the left side is $\log\left(\dfrac{9}{10} \times \dfrac{25}{27} \times \dfrac{6}{5}\right)$. The product is $\dfrac{9 \times 25 \times 6}{10 \times 27 \times 5} = \dfrac{1350}{1350} = 1$, so the left side is $\log 1 = 0$.

(c) The product law gives $\log x + \log y = \log (xy)$, so $\log (x + y) = \log (xy)$ and therefore $x + y = xy$. Then $xy - y = x$, so $y(x - 1) = x$ and $y = \dfrac{x}{x - 1}$ (with $x \ne 1$; in fact $x > 1$ because $y > 0$).`, sol: r`Parts (a) and (b) use the power, product and quotient laws and the fact $\log 1 = 0$. In part (c) two logarithms of the same base are equal only when their arguments are equal.`, scheme: [['(a) power law: log 36', 1], ['(a) quotient law: log(36/9)', 1], ['(a) log 4', 1], ['(b) combine with the product law', 1], ['(b) product of the fractions is 1350/1350 = 1', 1], ['(b) log 1 = 0', 1], ['(c) log(x + y) = log(xy), so x + y = xy', 2], ['(c) y(x - 1) = x', 1], ['(c) y = x/(x - 1)', 1]], d: 4, c: 'analysis', t: [3], time: 480 }), (C) => { C.assert(law([[2, 6], [-1, 9]], 4), '(a)'); C.assert(9 * 25 * 6 === 1350 && 10 * 27 * 5 === 1350 && vEq(vcomb([[1, [9, 10]], [1, [25, 27]], [1, [6, 5]]]), 1) && law([[1, [9, 10]], [1, [25, 27]], [1, [6, 5]]], 1), '(b)'); C.assert([3, 5, 2.5, 11].every((x) => { const y = x / (x - 1); return Math.abs(Math.log10(x + y) - (Math.log10(x) + Math.log10(y))) < 1e-12; }), '(c) y = x/(x - 1) satisfies the condition'); C.model(['36', '1350', '0']); });
Q('l07', mk.long({ marks: 10, stem: r`Two imagined rumours spread through a town. Rumour A starts with $5$ people and the number who know it doubles every hour, so after $n$ hours it is $5 \times 2^{n}$. Rumour B starts with $4$ people and triples every hour, so after $m$ hours it is $4 \times 3^{m}$. Use $\log 2 = 0.3010$ and $\log 3 = 0.4771$.

(a) Find the least whole number of hours after which rumour A is known by more than $4000$ people. [3]

(b) Find the least whole number of hours after which rumour B is known by more than $4000$ people. [3]

(c) Which rumour passes $4000$ people first, and by how many whole hours? Support your answer with the number of people who know each rumour after $7$ hours. [4]`, model: r`(a) $5 \times 2^{n} > 4000$ gives $2^{n} > 800$. Then $n\log 2 > \log 800 = 3\log 2 + 2 = 2.9030$, so $n > \dfrac{2.9030}{0.3010} = 9.64\ldots$. The least whole number is $n = 10$.

(b) $4 \times 3^{m} > 4000$ gives $3^{m} > 1000$. Then $m\log 3 > 3$, so $m > \dfrac{3}{0.4771} = 6.28\ldots$. The least whole number is $m = 7$.

(c) After $7$ hours rumour A is known by $5 \times 2^{7} = 640$ people and rumour B by $4 \times 3^{7} = 8748$ people. Rumour B passes $4000$ after $7$ hours and rumour A only after $10$ hours, so rumour B is first, by $10 - 7 = 3$ hours.`, sol: r`Each part turns a growth inequality into $n\log b > \ldots$ by taking logarithms, then rounds up to a whole number of hours.`, scheme: [['(a) 2^n > 800', 1], ['(a) n log 2 > 2.9030, n > 9.64', 1], ['(a) n = 10', 1], ['(b) 3^m > 1000, so m log 3 > 3', 1], ['(b) m > 6.28', 1], ['(b) m = 7', 1], ['(c) A after 7 hours is 640', 1], ['(c) B after 7 hours is 8748', 1], ['(c) B is first (7 hours against 10)', 1], ['(c) 3 hours earlier', 1]], d: 4, c: 'evaluation', t: [3], time: 540 }), (C) => { const firstN = (a, b) => { let n = 0; while (a * b ** n <= 4000) n++; return n; }; const l800 = dadd(dmul('3', '0.3010'), '2'); C.assert(l800 === '2.903' && law([[3, 2], [2, 10]], 800), '(a) log 800 = 2.9030'); const qa = Number(l800) / 0.301, qb = 3 / 0.4771; C.assert(qa > 9.64 && qa < 9.65 && Math.ceil(qa) === firstN(5, 2) && firstN(5, 2) === 10, '(a) n = 10'); C.assert(qb > 6.28 && qb < 6.29 && Math.ceil(qb) === firstN(4, 3) && firstN(4, 3) === 7 && firstPowerAbove(3, 1000) === 7, '(b) m = 7'); C.assert(5 * 2 ** 7 === 640 && 4 * 3 ** 7 === 8748 && firstN(4, 3) < firstN(5, 2) && firstN(5, 2) - firstN(4, 3) === 3, '(c) B first by 3 hours'); C.model([640, 8748, 3, 10]); });
